// B4-BL browser demo — entry point.
//
// Everything the demo knows about the language comes from data/language.json,
// which is generated by tools_export_language.py at the repo root. Never
// hand-edit that file and never hardcode a lexicon here: the whole point is
// that the demo cannot drift from the Python implementation.

import { initHear } from './hear.js';
import { initBuilder } from './builder.js';
import { initInventory } from './inventory.js';

async function main() {
  const language = await fetch('data/language.json').then(r => r.json());

  initHear();                  // static audio players; no language data needed
  initBuilder(language);       // template picker + slot dropdowns + synthesis
  initInventory(language);     // phoneme grid + vocabulary table
}

main().catch(err => {
  console.error('B4-BL demo failed to start:', err);
});
